import sys


def main():
    text = sys.stdin.read()
    if "===\n" not in text:
        return
    config, _, queries = text.partition("===\n")
    data = {}
    current_section = None
    for line in config.splitlines():
        line = line.strip()
        if not line or line.startswith(";"):
            continue
        if line.startswith("["):
            current_section = line[1:-1].strip().lower()
            if current_section not in data:
                data[current_section] = {}
            continue
        if "=" not in line:
            continue
        key, value = line.split("=", 1)
        key = key.strip().lower()
        value = value.strip()
        if value.startswith('"'):
            end_quote = value.find('"', 1)
            if end_quote == -1:
                raise ValueError(f"Unclosed quote in value: {value}")
            value = value[1:end_quote]
        else:
            comment_start = value.find(';', 0)
            if comment_start != -1 and (comment_start > 0 or value[comment_start - 1].isspace()):
                value = value[:comment_start].rstrip()
        data[current_section].setdefault(key, "") = value

    for query_line in queries.splitlines():
        query_line = query_line.strip()
        if not query_line:
            continue
        parts = query_line.split(".", 1)
        if len(parts) != 2:
            print("NOT FOUND")
            continue
        section, key = parts
        section = section.strip().lower()
        key = key.strip().lower()
        value = data.get(section, {}).get(key, "NOT FOUND")
        print(value)


if __name__ == "__main__":
    main()
